export const matchOpportunitiesResponseTargetsTuitionSupportAmountMin = 0;

export const matchOpportunitiesResponseTargetsMonthlyIncomeAmountMin = 0;

export const matchOpportunitiesResponseTargetsSemesterIncomeAmountMin = 0;

export const matchOpportunitiesResponseTargetsCurrentGapMin = 0;

export const matchOpportunitiesResponseOpportunitiesItemEstimatedAmountMin = 0;



export const MatchOpportunitiesResponse = zod.object({
  "targets": zod.object({
  "tuitionSupportAmount": zod.number().min(matchOpportunitiesResponseTargetsTuitionSupportAmountMin),
  "monthlyIncomeAmount": zod.number().min(matchOpportunitiesResponseTargetsMonthlyIncomeAmountMin),
  "semesterIncomeAmount": zod.number().min(matchOpportunitiesResponseTargetsSemesterIncomeAmountMin),
  "currentGap": zod.number().min(matchOpportunitiesResponseTargetsCurrentGapMin)
}),
  "opportunities": zod.array(zod.object({
  "id": zod.string(),
  "name": zod.string(),
  "provider": zod.string(),
  "sourceUrl": zod.string().url(),
  "type": zod.enum(['scholarship', 'aid', 'paid-opportunity']),
  "amount": zod.string(),
  "estimatedAmount": zod.number().min(matchOpportunitiesResponseOpportunitiesItemEstimatedAmountMin).nullable(),
  "deadline": zod.string(),
  "requirements": zod.array(zod.string()),
  "verificationStatus": zod.enum(['verified-source']),
  "verifiedAt": zod.coerce.date(),
  "impactExplanation": zod.string(),
  "relevanceExplanation": zod.string(),
  "eligibilityNotice": zod.string()
})),
  "disclaimer": zod.string()
})


/**
 * @summary Create a CampusOne account
 */
export const signUpBodyNameMax = 100;

export const signUpBodyEmailMax = 254;

export const signUpBodyPasswordMin = 8;
export const signUpBodyPasswordMax = 128;



export const SignUpBody = zod.object({
  "name": zod.string().min(1).max(signUpBodyNameMax),
  "email": zod.string().email().max(signUpBodyEmailMax),
  "password": zod.string().min(signUpBodyPasswordMin).max(signUpBodyPasswordMax)
})




export const signUpResponseProfileOneCostPerCreditMin = 0;

export const signUpResponseProfileOneSemesterDurationMax = 12;

export const signUpResponseProfileOneMonthlyIncomeMin = 0;

export const signUpResponseProfileOneTransportationMin = 0;

export const signUpResponseProfileOneFoodMin = 0;

export const signUpResponseProfileOneOtherExpensesMin = 0;


export const signUpResponseProfileOneTuitionPaymentsItemAmountMin = 0;



export const SignUpResponse = zod.object({
  "authenticated": zod.boolean(),
  "user": zod.union([zod.object({
  "id": zod.string(),
  "name": zod.string(),
  "email": zod.string().email()
}),zod.null()]),
  "profile": zod.union([zod.object({
  "name": zod.string().min(1),
  "major": zod.string().min(1),
  "creditHours": zod.number().int().min(1),
  "costPerCredit": zod.number().min(signUpResponseProfileOneCostPerCreditMin),
  "semesterDuration": zod.number().int().min(1).max(signUpResponseProfileOneSemesterDurationMax),
  "currentBalance": zod.number(),
  "monthlyIncome": zod.number().min(signUpResponseProfileOneMonthlyIncomeMin),
  "transportation": zod.number().min(signUpResponseProfileOneTransportationMin),
  "food": zod.number().min(signUpResponseProfileOneFoodMin),
  "otherExpenses": zod.number().min(signUpResponseProfileOneOtherExpensesMin),
  "tuitionPayments": zod.array(zod.object({
  "month": zod.number().int().min(1),
  "amount": zod.number().min(signUpResponseProfileOneTuitionPaymentsItemAmountMin)
}))
}),zod.null()])
})


